SELECT orders.channel, COUNT(shipments.id) AS shipment_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(shipments.status))) AS status_values, COUNT(CASE WHEN shipments.status = 'LOST' THEN 1 END) AS lost_count FROM orders LEFT OUTER JOIN shipments ON shipments.order_id = orders.id WHERE orders.status IN ('CANCELLED', 'SHIPPED') GROUP BY orders.channel ORDER BY lost_count DESC, status_values
